      "option_d": "急傾斜地崩壊危険区域内においては、水の浸透を助長する行為、急傾斜地崩壊防止施設以外の施設等の設置、法面の掘削等の改変、立木等の伐採等の行為は、市町村長の許可を受けなければ、してはならない。ただし、非常災害等の場合はこの限りでない。",
