      "question": "土石流・流木対策計画における土砂量および流木量の調査・算出方法に関する記述として、正しいものを a～d のなかから選びなさい。[cite: 3]",
      "figure_image": null,
      "option_a": "計画流出土砂量は、原則として流域内の移動可能土砂量と、「計画規模の土石流」によって運搬できる土砂量を比較して小さい方の値とする。",
      "option_b": "崩壊可能土砂量を算出する際に考慮する 0 次谷とは、1/5,000 以上で最も大縮尺となる地形図や航空レーザ測量結果を使用して等高線の凹み具合を眺めて、凹んでいる等高線群の間口よりも奥行が小なる地形とする。",
      "option_c": "「計画規模の土石流」によって運搬できる土砂量は、計画規模の年超過確率の降雨量と既往最大の降雨量を比較し、値の大きい降雨量（Pp （mm））に流域面積（A（km2））を掛けて総水量を求め、これに流動中の土石流濃度（Cd）を乗じて算定する。その際流出補正率（Kr2) を考慮する。",
